library(testthat)

val_get_row <- function(df, v1, v2, grp = NULL) {
  idx <- df$var1 == v1 & df$var2 == v2
  if (!is.null(grp) && "group" %in% names(df)) {
    idx <- idx & as.character(df$group) == grp
  }
  stopifnot(sum(idx) == 1L)
  df[idx, , drop = FALSE]
}

