test_that("C01/C02/C03/C17: zero-order Pearson r, Fisher-z CI, t-test p and listwise N match hand arithmetic", {
  # Oracle: exact hand arithmetic on n=8 complete cases with 1 tie and 1 NA row
  d <- data.frame(
    x = c(1, 2, 2, 4, 5, 6, 8, 10, NA),
    y = c(2, 3, 5, 4, 8, 7, 11, 12, 99)
  )
  exp_r <- 77 / sqrt(69.5 * 94)
  exp_t <- exp_r * sqrt(6 / (1 - exp_r^2))
  exp_p <- 2 * stats::pt(-abs(exp_t), df = 6)
  exp_ci <- tanh(atanh(exp_r) + c(-1, 1) * stats::qnorm(0.975) / sqrt(8 - 3))

  res <- jjcorrmat(
    data = d, dep = c("x", "y"),
    typestatistics = "parametric", padjustmethod = "none", conflevel = 0.95
  )
  tb <- res$table$asDF
  expect_equal(tb$n[1], 8L)
  expect_equal(tb$r[1], exp_r, tolerance = 1e-12)
  expect_equal(c(tb$conf_low[1], tb$conf_high[1]), exp_ci, tolerance = 1e-12)
  expect_equal(tb$p[1], exp_p, tolerance = 1e-12)
})

test_that("C04/C05/C06: zero-order Spearman rho, Fieller CI and asymptotic p match hand arithmetic", {
  # Oracle: exact hand average-rank Pearson r, Fieller (1957) SE=sqrt(1.06/(n-3)), t-approx df=n-2
  d <- data.frame(
    x = c(1, 2, 2, 4, 5, 6, 8, 10, NA),
    y = c(2, 3, 5, 4, 8, 7, 11, 12, 99)
  )
  exp_rho <- 39 / sqrt(41.5 * 42)
  exp_ci <- tanh(atanh(exp_rho) + c(-1, 1) * stats::qnorm(0.975) * sqrt(1.06 / (8 - 3)))
  exp_p <- 2 * stats::pt(-abs(exp_rho * sqrt(6 / (1 - exp_rho^2))), df = 6)

  res <- jjcorrmat(
    data = d, dep = c("x", "y"),
    typestatistics = "nonparametric", padjustmethod = "none", conflevel = 0.95
  )
  tb <- res$table$asDF
  expect_equal(tb$r[1], exp_rho, tolerance = 1e-12)
  expect_equal(c(tb$conf_low[1], tb$conf_high[1]), exp_ci, tolerance = 1e-12)
  expect_equal(tb$p[1], exp_p, tolerance = 1e-12)
})

test_that("C07: zero-order Winsorized Pearson point estimate matches hand winsorization and WRS2::wincor", {
  # Oracle: exact 20% tail clamping (g = floor(0.2*10) = 2) and WRS2::wincor(tr = 0.2)$cor
  skip_if_not_installed("WRS2")
  d <- data.frame(
    x = c(-100, 1, 2, 3, 4, 5, 6, 7, 8, 500),
    y = c(50,   2, 3, 5, 4, 6, 8, 7, 9, -200)
  )
  xw <- c(2, 2, 2, 3, 4, 5, 6, 7, 7, 7)
  yw <- c(8, 3, 3, 5, 4, 6, 8, 7, 8, 3)
  exp_rw <- stats::cor(xw, yw)

  res <- jjcorrmat(
    data = d, dep = c("x", "y"),
    typestatistics = "robust", padjustmethod = "none"
  )
  expect_equal(res$table$asDF$r[1], exp_rw, tolerance = 1e-12)
  expect_equal(res$table$asDF$r[1], WRS2::wincor(d$x, d$y, tr = 0.2)$cor, tolerance = 1e-12)
})

