test_that("C01/C04/C18: metamorphic invariances (permutation, affine, zero-order Spearman monotone, subgroup split)", {
  # Oracle: mathematical invariance properties of Pearson, Spearman, and unpooled subgrouping
  set.seed(101)
  n <- 45
  d <- data.frame(
    a = rnorm(n, 10, 3),
    b = rnorm(n, 20, 4),
    c = rnorm(n, 5, 2),
    g = factor(rep(c("High", "Low", "Mid"), each = 15), levels = c("Mid", "High", "Low"))
  )
  d$b <- 0.65 * d$a + rnorm(n, 0, 2)
  d$c <- 0.50 * d$a + 0.30 * d$b + rnorm(n, 0, 1.5)

  base_tb <- jjcorrmat(data = d, dep = c("a", "b", "c"), padjustmethod = "holm")$table$asDF
  perm_tb <- jjcorrmat(data = d[sample(n), ], dep = c("a", "b", "c"), padjustmethod = "holm")$table$asDF
  expect_equal(perm_tb$r, base_tb$r, tolerance = 1e-12)
  expect_equal(perm_tb$p_adj, base_tb$p_adj, tolerance = 1e-12)

  d_neg <- d; d_neg$a <- -3 * d_neg$a + 50
  neg_tb <- jjcorrmat(data = d_neg, dep = c("a", "b", "c"), padjustmethod = "holm")$table$asDF
  expect_equal(neg_tb$r, ifelse(base_tb$var1 == "a" | base_tb$var2 == "a", -base_tb$r, base_tb$r), tolerance = 1e-12)
  expect_equal(neg_tb$p, base_tb$p, tolerance = 1e-12)

  d_exp <- d; d_exp$a <- exp(d$a / 5); d_exp$b <- exp(d$b / 10); d_exp$c <- exp(d$c / 5)
  sp1 <- jjcorrmat(data = d, dep = c("a", "b", "c"), typestatistics = "nonparametric")$table$asDF
  sp2 <- jjcorrmat(data = d_exp, dep = c("a", "b", "c"), typestatistics = "nonparametric")$table$asDF
  expect_equal(sp2$r, sp1$r, tolerance = 1e-12)

  grp_tb <- jjcorrmat(data = d, dep = c("a", "b", "c"), grvar = "g", padjustmethod = "holm")$table$asDF
  expect_equal(unique(as.character(grp_tb$group)), c("Mid", "High", "Low"))
  sub_tb <- jjcorrmat(data = d[d$g == "Mid", ], dep = c("a", "b", "c"), padjustmethod = "holm")$table$asDF
  expect_equal(grp_tb$r[grp_tb$group == "Mid"], sub_tb$r, tolerance = 1e-12)
  expect_equal(grp_tb$p_adj[grp_tb$group == "Mid"], sub_tb$p_adj, tolerance = 1e-12)
})

