test_that("C12 [VAL-JJCORRMAT-01]: partial Pearson uses df = n - 2 - q, SE = 1/sqrt(n - 3 - q), and refuses saturated n = p", {
  # Oracle: Fisher (1924) exact partial correlation test & lm(y ~ x + z) t-test
  d <- data.frame(
    x = c(1, 2, 3, 4, 5, 6, 7, 8),
    y = c(2, 4, 5, 4, 7, 8, 9, 12),
    z = c(1, 1, 2, 3, 3, 5, 6, 7)
  )
  fit <- stats::lm(y ~ x + z, data = d)
  exp_p <- summary(fit)$coefficients["x", "Pr(>|t|)"]
  r_part <- (stats::cor(d$x, d$y) - stats::cor(d$x, d$z) * stats::cor(d$y, d$z)) /
    sqrt((1 - stats::cor(d$x, d$z)^2) * (1 - stats::cor(d$y, d$z)^2))
  exp_ci <- tanh(atanh(r_part) + c(-1, 1) * stats::qnorm(0.975) / sqrt(8 - 3 - 1))

  rw <- val_get_row(
    jjcorrmat(data = d, dep = c("x", "y", "z"), partial = TRUE, padjustmethod = "none")$table$asDF,
    "x", "y"
  )
  expect_equal(rw$p, exp_p, tolerance = 1e-8)
  expect_equal(c(rw$conf_low, rw$conf_high), exp_ci, tolerance = 1e-8)

  # Saturated n = 5, p = 5 (df = 0) must not produce finite p-values
  set.seed(123)
  d_sat <- as.data.frame(matrix(rnorm(25), nrow = 5, ncol = 5))
  names(d_sat) <- paste0("v", 1:5)
  tb_sat <- jjcorrmat(data = d_sat, dep = !!names(d_sat), partial = TRUE, padjustmethod = "none")$table$asDF
  expect_true(nrow(tb_sat) == 0L || all(is.na(tb_sat$p)))
})

test_that("C11/C15 [VAL-JJCORRMAT-02]: Bayesian credible intervals honor conflevel (0.80 < 0.95 < 0.99)", {
  # Oracle: monotone widening of HDI credible intervals with conflevel
  set.seed(101)
  d <- data.frame(a = rnorm(45), b = rnorm(45))
  d$b <- 0.65 * d$a + rnorm(45, 0, 0.7)
  t80 <- jjcorrmat(data = d, dep = c("a", "b"), typestatistics = "bayes", conflevel = 0.80, bayesseed = 42)$table$asDF
  t95 <- jjcorrmat(data = d, dep = c("a", "b"), typestatistics = "bayes", conflevel = 0.95, bayesseed = 42)$table$asDF
  t99 <- jjcorrmat(data = d, dep = c("a", "b"), typestatistics = "bayes", conflevel = 0.99, bayesseed = 42)$table$asDF
  expect_lt(t99$cred_low[1], t95$cred_low[1])
  expect_lt(t95$cred_low[1], t80$cred_low[1])
  expect_gt(t99$cred_high[1], t95$cred_high[1])
  expect_gt(t95$cred_high[1], t80$cred_high[1])
})

