test_that("C17 [VAL-JJCORRMAT-05]: partial correlation with pairwise NA handling uses a consistent sample", {
  # Oracle: psych::partial.r on complete cases (or pairwise covariance matrix)
  skip_if_not_installed("psych")
  set.seed(303)
  d <- data.frame(x = rnorm(30), y = rnorm(30), z = rnorm(30))
  d$y <- 0.5 * d$x + 0.5 * d$z + rnorm(30, 0, 0.7)
  d$x[1:5] <- NA; d$z[6:10] <- NA
  obs <- val_get_row(jjcorrmat(data = d, dep = c("x", "y", "z"), partial = TRUE, naHandling = "pairwise")$table$asDF, "x", "y")$r
  exact_cc <- psych::partial.r(d[stats::complete.cases(d), ])["x", "y"]
  exact_pw <- psych::partial.r(stats::cor(d, use = "pairwise.complete.obs"))["x", "y"]
  expect_true(isTRUE(all.equal(obs, exact_cc, tolerance = 1e-8)) ||
              isTRUE(all.equal(obs, exact_pw, tolerance = 1e-8)))
})

