test_that("C20/C21/C25/C26 [VAL-JJCORRMAT-13..17]: partial method label, grouped constant/pairwise narrative, r=0 label, Bayes prior disclosure, patchwork caption", {
  set.seed(101)
  d <- data.frame(a = rnorm(30), b = rnorm(30), c = rnorm(30), g = factor(rep(c("A", "B"), each = 15)))
  tb_p <- jjcorrmat(data = d, dep = c("a", "b", "c"), partial = TRUE)$table$asDF
  expect_match(tb_p$method[1], "Partial", ignore.case = TRUE)

  a_obj <- ClinicoPath:::jjcorrmatClass$new(options = ClinicoPath:::jjcorrmatOptions$new(dep = c("a", "b")), data = d)
  expect_false(grepl("negative", a_obj$.__enclos_env__$private$.interpretCorrelation(0, 1), ignore.case = TRUE))
  expect_false(grepl("moderate-to-strong", a_obj$.__enclos_env__$private$.interpretCorrelation(0.35, 0.20), fixed = TRUE))

  assump <- jjcorrmat(data = d, dep = c("a", "b"), typestatistics = "bayes", showexplanations = TRUE)$assumptions$content
  expect_match(assump, "0.707", fixed = TRUE)

  d_const <- data.frame(a = c(rnorm(20), rep(1, 20)), b = rnorm(40), g = factor(rep(c("ValidGrp", "ConstGrp"), each = 20)))
  interp_c <- jjcorrmat(data = d_const, dep = c("a", "b"), grvar = "g", showexplanations = TRUE)$interpretation$content
  expect_match(interp_c, "ConstGrp", fixed = TRUE)

  # Patchwork caption preservation in addSeedCaption()
  a_g <- ClinicoPath:::jjcorrmatClass$new(
    options = ClinicoPath:::jjcorrmatOptions$new(dep = c("a", "b", "c"), grvar = "g", typestatistics = "bayes", caption = "Custom Footnote"),
    data = d
  )
  a_g$init(); a_g$run()
  p2_c <- a_g$.__enclos_env__$private$.buildPlot2(
    a_g$.__enclos_env__$private$.prepareData(),
    a_g$.__enclos_env__$private$.prepareOptions()
  )
  cap_str <- paste(as.character(p2_c$patches$annotation$caption), collapse = " ")
  expect_match(cap_str, "Custom Footnote", fixed = TRUE)
  expect_match(cap_str, "20250101", fixed = TRUE)
})

