  d <- as.data.frame(matrix(rnorm(12 * 10), nrow = 12, ncol = 10))
  names(d) <- paste0("v", 1:10)
  rw <- val_get_row(
    jjcorrmat(data = d, dep = !!names(d), typestatistics = "bayes", partial = TRUE, bayesseed = 20250101)$table$asDF,
    "v1", "v7"
  )
  r_p <- psych::partial.r(d)["v1", "v7"]
  n_eff <- 12L - 8L
  u <- seq_len(n_eff) - (n_eff + 1) / 2; u <- u / sqrt(sum(u^2))
  w <- u^2 - mean(u^2); w <- w - sum(w * u) * u; w <- w / sqrt(sum(w^2))
  v <- r_p * u + sqrt(1 - r_p^2) * w
  bf_exact <- as.numeric(BayesFactor::extractBF(BayesFactor::correlationBF(u, v, rscale = 0.707))$bf)
  expect_equal(rw$bf, bf_exact, tolerance = 1e-6)
  expect_lt(rw$cred_low, 0)
  expect_gt(rw$cred_high, 0)
})

test_that("IND-JJCORRMAT-02: reused R6 instance clears stale outputs on error and invalidates cache on value edits", {
  # Oracle: jamovi lifecycle state hygiene on reused Analysis instance
  set.seed(1)
  d1 <- data.frame(a = 1:25, b = 1:25 + rnorm(25, 0, 0.1))
  d2 <- data.frame(a = 1:25, b = -(1:25) + rnorm(25, 0, 0.1))
  a_obj <- ClinicoPath:::jjcorrmatClass$new(
    options = ClinicoPath:::jjcorrmatOptions$new(dep = c("a", "b"), showexplanations = TRUE),
    data = d1
  )
  a_obj$init(); a_obj$run()
  expect_gt(a_obj$results$table$asDF$r[1], 0.9)

  # Value edit with identical dim & names must recompute
  a_obj$.__enclos_env__$private$.data <- d2
  a_obj$run()
  expect_lt(a_obj$results$table$asDF$r[1], -0.9)

  # Transition to empty data must clear stale rows and narrative
  a_obj$.__enclos_env__$private$.data <- data.frame(a = numeric(0), b = numeric(0))
  a_obj$run()
  expect_equal(a_obj$results$table$rowCount, 0L)
  expect_identical(a_obj$results$interpretation$content, "")
})

test_that("IND-JJCORRMAT-04: constant or post-winsorization collapsed control var drops Partial label and warns", {
  # Oracle: q = 0 active control variables is zero-order, not partial
  set.seed(1)
  d_const <- data.frame(a = rnorm(25), b = rnorm(25), flat = 5)
  res_c <- jjcorrmat(data = d_const, dep = c("a", "b", "flat"), partial = TRUE)
  expect_false(grepl("^Partial ", val_get_row(res_c$table$asDF, "a", "b")$method))

  d_zi <- data.frame(a = rnorm(25), b = rnorm(25), necrosis = c(rep(0, 22), 10, 20, 30))
  res_zi <- jjcorrmat(data = d_zi, dep = c("a", "b", "necrosis"), typestatistics = "robust", partial = TRUE)
  expect_match(res_zi$warnings$content, "WARNING:")
  expect_match(res_zi$warnings$content, "necrosis", fixed = TRUE)
  expect_false(grepl("^Partial ", val_get_row(res_zi$table$asDF, "a", "b")$method))
})

test_that("IND-JJCORRMAT-05: invalid color strings fall back safely with a warning instead of crashing plot render", {
  # Oracle: defensive color validation in .prepareOptions()
  set.seed(1)
  d <- data.frame(a = rnorm(25), b = rnorm(25))
  res <- jjcorrmat(data = d, dep = c("a", "b"), lowcolor = "not_a_real_color")
  expect_match(res$warnings$content, "Invalid color", fixed = TRUE)
  tf <- tempfile(fileext = ".png")
  expect_no_error(res$plot$saveAs(tf))
  expect_true(file.exists(tf) && file.info(tf)$size > 1000)
})

test_that("REL-JJCORRMAT-01: .computeCorrelations memoization hits cache across consumers and invalidates on seed/data change", {
  set.seed(7)
  d <- data.frame(a = rnorm(30), b = rnorm(30), c = rnorm(30))
  opts <- ClinicoPath:::jjcorrmatOptions$new(
    dep = c("a", "b", "c"),
    typestatistics = "bayes",
    bayesseed = 20250101,
    showexplanations = TRUE
  )
  a_obj <- ClinicoPath:::jjcorrmatClass$new(options = opts, data = d)
  a_obj$run()
  priv <- a_obj$.__enclos_env__$private
  expect_equal(length(priv$.corr_cache), 1L)

  # Building the plot on the same data/options must hit the warm cache (no new entry)
  p <- priv$.buildPlot(priv$.prepareData(), priv$.prepareOptions())
  expect_s3_class(p, "ggplot")
  expect_equal(length(priv$.corr_cache), 1L)

  # Changing data values must miss cache and recompute cleanly
  d2 <- d
  d2$b <- -d2$a + rnorm(30, sd = 0.05)
  a_obj$.__enclos_env__$private$.data <- d2
  a_obj$run()
  expect_equal(length(priv$.corr_cache), 2L)
  expect_lt(val_get_row(a_obj$results$table$asDF, "a", "b")$r, -0.95)
})

test_that("SEC-JJCORRMAT-01: asSource/.sourcifyOption blocks quote-break, undeclared option, and list injection", {
  d <- datasets::mtcars[, c("mpg", "hp", "wt")]
  payloads <- c(
    'ok", k = {stop("X"); 2}, subtitle = "x',
    'trailing\\',
    "line1\nline2\", k = {stop(\"X\"); 2}, subtitle = \"x"
  )

  # 1. OptionString (title) and OptionList (typestatistics) quote/backslash/newline payloads
  for (opt_nm in c("title", "typestatistics")) {
    for (p in payloads) {
      opts <- ClinicoPath:::jjcorrmatOptions$new(dep = c("mpg", "hp", "wt"))
      an <- ClinicoPath:::jjcorrmatClass$new(options = opts, data = d)
      o <- an$options$option(opt_nm)
      o$value <- p
      ex <- parse(text = an$asSource())[[1]]
      mc <- match.call(ClinicoPath::jjcorrmat, ex)
      expect_identical(ex[[opt_nm]], p)
      expect_false("k" %in% names(mc))
      expect_false("subtitle" %in% names(mc))
    }
  }

  # 2. Undeclared option name must be dropped
  opts_u <- ClinicoPath:::jjcorrmatOptions$new(dep = c("mpg", "hp", "wt"))
  an_u <- ClinicoPath:::jjcorrmatClass$new(options = opts_u, data = d)
  an_u$options$.addOption(jmvcore:::Option$new('title = "a", k = {stop("X"); 2}, subtitle', "b"))
  ex_u <- parse(text = an_u$asSource())[[1]]
  mc_u <- match.call(ClinicoPath::jjcorrmat, ex_u)
  expect_false("k" %in% names(mc_u))
  expect_false("title" %in% names(mc_u))

  # 3. List payload on scalar option must be dropped
  opts_l <- ClinicoPath:::jjcorrmatOptions$new(dep = c("mpg", "hp", "wt"))
  an_l <- ClinicoPath:::jjcorrmatClass$new(options = opts_l, data = d)
  o_sub <- an_l$options$option("subtitle")
  o_sub$value <- list("a" = 'x", k = {stop("X"); 2}, caption = "y')
  ex_l <- parse(text = an_l$asSource())[[1]]
  mc_l <- match.call(ClinicoPath::jjcorrmat, ex_l)
  expect_false("subtitle" %in% names(mc_l))
  expect_false("k" %in% names(mc_l))
})

test_that("SEC-JJCORRMAT-02: backend .prepareOptions rejects out-of-range conflevel and invalid typestatistics", {
  d <- datasets::mtcars[, c("mpg", "hp", "wt")]
  opts1 <- ClinicoPath:::jjcorrmatOptions$new(dep = c("mpg", "hp", "wt"))
  an1 <- ClinicoPath:::jjcorrmatClass$new(options = opts1, data = d)
  o1 <- an1$options$option("conflevel")
  o1$value <- 1.5
  expect_error(an1$.__enclos_env__$private$.prepareOptions(), "Confidence")

  opts2 <- ClinicoPath:::jjcorrmatOptions$new(dep = c("mpg", "hp", "wt"))
  an2 <- ClinicoPath:::jjcorrmatClass$new(options = opts2, data = d)
  o2 <- an2$options$option("typestatistics")
  o2$value <- "bogus_method"
  expect_error(an2$.__enclos_env__$private$.prepareOptions(), "Invalid correlation method")
})
